"""Server-side trust ledger for answers generated by the RAG/Agent pipeline.

The chat API intentionally accepts ordinary client-authored rows so the history
workspace can keep notes and failed turns. That means a row in ``chat_messages``
is not, by itself, evidence that the server produced the answer or verified its
numbers. This module persists an HMAC-signed record for every answer the server
streamed to a client, binding:

* the conversation and knowledge base,
* the exact answer text and citation JSON,
* the application-assigned fact provenance / safety gate,
* the sanitized tool execution trace.

Report auto-insertion requires a valid record for the exact stored content and
citations. The browser cannot forge one because it never sees the signing key.
Records live under ``<data_dir>/agent-trust`` so no database migration is needed;
the signing key is generated once and stored next to them with mode 0o600.
"""

from __future__ import annotations

import hashlib
import hmac
import json
import logging
import os
import secrets
import time
from collections.abc import Sequence
from datetime import UTC, datetime
from pathlib import Path
from typing import Any, Literal
from uuid import UUID

from pydantic import BaseModel, ConfigDict, Field, ValidationError

from knowledge_scope.rag.schemas import RAGCitation, RAGCompleteData
from knowledge_scope.shared.config import Settings

logger = logging.getLogger(__name__)

TRUST_DIRECTORY_NAME = "agent-trust"
TRUST_SECRET_FILENAME = ".trust-secret"
TRUST_SCHEMA_VERSION = "1.0"
_SECRET_BYTES = 32

GenerationSource = Literal["agent", "rag", "safety_gate"]


class TrustStoreError(RuntimeError):
    """The trust ledger could not be read, written, or validated."""


class TrustedAnswer(BaseModel):
    """One verified server-generated answer."""

    model_config = ConfigDict(extra="forbid")

    schema_version: Literal["1.0"] = TRUST_SCHEMA_VERSION
    trust_id: str = Field(pattern=r"^[0-9a-f]{64}$")
    conversation_id: UUID
    knowledge_base_id: UUID
    content_sha256: str = Field(pattern=r"^[0-9a-f]{64}$")
    citations_sha256: str = Field(pattern=r"^[0-9a-f]{64}$")
    citations: list[RAGCitation]
    generation_source: GenerationSource
    fact_status: str | None = None
    safety_gate: str = "none"
    safety_notice: str | None = None
    tool_trace: list[dict[str, Any]] = Field(default_factory=list)
    created_at: datetime


def _trust_root(settings: Settings) -> Path:
    root = (Path(settings.data_dir) / TRUST_DIRECTORY_NAME).resolve()
    root.mkdir(mode=0o700, parents=True, exist_ok=True)
    if root.is_symlink() or not root.is_dir():
        raise TrustStoreError("agent trust directory is not a regular directory")
    return root


def _read_secret_file(path: Path) -> bytes:
    """Read a complete secret file, tolerating a concurrent first writer.

    Multiple workers may discover a missing key at the same time. Exactly one
    process creates the file; the others wait until the 64 hex characters are
    fully written instead of reading a partial value.
    """

    for _ in range(200):
        try:
            raw = path.read_text(encoding="ascii").strip()
        except OSError:
            raw = ""
        if len(raw) == _SECRET_BYTES * 2:
            try:
                return bytes.fromhex(raw)
            except ValueError:
                pass
        time.sleep(0.01)
    raise TrustStoreError("agent trust secret could not be read consistently")


def _trust_secret(settings: Settings) -> bytes:
    configured = settings.agent_trust_secret
    if configured is not None:
        value = configured.get_secret_value()
        if len(value) < 16:
            raise TrustStoreError("configured agent trust secret is too short")
        return value.encode("utf-8")
    path = _trust_root(settings) / TRUST_SECRET_FILENAME
    if path.exists():
        if path.is_symlink() or not path.is_file():
            raise TrustStoreError("agent trust secret is not a regular file")
        return _read_secret_file(path)
    try:
        descriptor = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    except FileExistsError:
        # Another worker won the creation race; wait for its secret.
        return _read_secret_file(path)
    secret = secrets.token_bytes(_SECRET_BYTES)
    try:
        with os.fdopen(descriptor, "wb") as handle:
            handle.write(secret.hex().encode("ascii"))
            handle.flush()
            os.fsync(handle.fileno())
    except Exception:
        path.unlink(missing_ok=True)
        raise
    return secret


def _atomic_write(path: Path, data: bytes) -> None:
    temporary = path.with_name(f".{path.name}.{secrets.token_hex(8)}.tmp")
    descriptor = os.open(temporary, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    try:
        with os.fdopen(descriptor, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
    except Exception:
        temporary.unlink(missing_ok=True)
        raise


def _canonical_json(value: Any) -> bytes:
    return json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")


def _sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def content_fingerprint(content: str) -> str:
    """Stable fingerprint of the exact answer text."""

    return _sha256(content.encode("utf-8"))


def citations_fingerprint(citations: Sequence[RAGCitation]) -> str:
    """Stable fingerprint of the canonical citation objects."""

    canonical = [citation.model_dump(mode="json") for citation in citations]
    return _sha256(_canonical_json(canonical))


def _trust_id_for(
    *,
    conversation_id: UUID,
    knowledge_base_id: UUID,
    content_sha256: str,
    citations_sha256: str,
) -> str:
    binding = {
        "binding_version": "trust-v1",
        "conversation_id": str(conversation_id),
        "knowledge_base_id": str(knowledge_base_id),
        "content_sha256": content_sha256,
        "citations_sha256": citations_sha256,
    }
    return _sha256(_canonical_json(binding))


_SAFETY_GATE_RANK: dict[str, int] = {
    "none": 0,
    "visual_unverified": 1,
    "vision_unavailable": 2,
    "unverified_numbers_withheld": 2,
    "visual_numeric_withheld": 3,
}


def _safety_payload(complete: RAGCompleteData) -> dict[str, Any]:
    """Application-assigned safety state committed together with the answer."""

    return {
        "fact_status": complete.fact_status,
        "safety_gate": complete.safety_gate,
        "safety_notice": complete.safety_notice,
        "tool_trace": [item.model_dump(mode="json") for item in (complete.agent_tool_trace or [])],
    }


def _safety_restrictiveness(payload: dict[str, Any]) -> int:
    return _SAFETY_GATE_RANK.get(str(payload.get("safety_gate") or "none"), 0)


def _existing_payload(settings: Settings, path: Path) -> dict[str, Any] | None:
    """Return the existing signed payload, or None when it is unusable."""

    if not path.is_file() or path.is_symlink():
        return None
    try:
        record = json.loads(path.read_text(encoding="utf-8"))
        payload = record.get("payload")
        signature = record.get("signature")
        if not isinstance(payload, dict) or not isinstance(signature, str):
            return None
        expected = hmac.new(
            _trust_secret(settings),
            _canonical_json(payload),
            hashlib.sha256,
        ).hexdigest()
        if not hmac.compare_digest(expected, signature):
            return None
        return payload
    except (OSError, ValueError, TrustStoreError):
        return None


def record_streamed_answer(
    settings: Settings,
    *,
    conversation_id: UUID,
    knowledge_base_id: UUID,
    content: str,
    citations: Sequence[RAGCitation],
    answer_mode: str,
    complete: RAGCompleteData,
) -> str | None:
    """Persist a signed trust record for one server-generated answer.

    Returns the trust id, or ``None`` when the ledger is disabled. Failures are
    raised so the API layer can log them and continue serving the answer; report
    insertion simply stays unavailable for that answer.
    """

    if not settings.agent_trust_enabled:
        return None
    content_sha = content_fingerprint(content)
    citations_sha = citations_fingerprint(citations)
    if complete.safety_gate != "none":
        generation_source: GenerationSource = "safety_gate"
    elif answer_mode == "agent":
        generation_source = "agent"
    else:
        generation_source = "rag"
    safety = _safety_payload(complete)
    trust_id = _trust_id_for(
        conversation_id=conversation_id,
        knowledge_base_id=knowledge_base_id,
        content_sha256=content_sha,
        citations_sha256=citations_sha,
    )
    payload: dict[str, Any] = {
        "schema_version": TRUST_SCHEMA_VERSION,
        "trust_id": trust_id,
        "conversation_id": str(conversation_id),
        "knowledge_base_id": str(knowledge_base_id),
        "content_sha256": content_sha,
        "citations_sha256": citations_sha,
        "citations": [citation.model_dump(mode="json") for citation in citations],
        "generation_source": generation_source,
        **safety,
        "created_at": datetime.now(UTC).isoformat(),
    }
    signature = hmac.new(
        _trust_secret(settings),
        _canonical_json(payload),
        hashlib.sha256,
    ).hexdigest()
    record = {
        "schema_version": TRUST_SCHEMA_VERSION,
        "payload": payload,
        "signature": signature,
    }
    path = _trust_root(settings) / f"{trust_id}.json"
    existing = _existing_payload(settings, path)
    if existing is not None and _safety_restrictiveness(existing) > _safety_restrictiveness(
        payload
    ):
        # Identical text/citations produced again with a less restrictive safety
        # state must not downgrade the record that users may have already seen.
        return trust_id
    _atomic_write(path, json.dumps(record, ensure_ascii=False).encode("utf-8"))
    return trust_id


def verify_streamed_answer(
    settings: Settings,
    *,
    conversation_id: UUID,
    knowledge_base_id: UUID,
    content: str,
    citations: Sequence[RAGCitation],
) -> TrustedAnswer | None:
    """Return the trusted record matching exactly this stored answer, if any."""

    if not settings.agent_trust_enabled:
        return None
    try:
        content_sha = content_fingerprint(content)
        citations_sha = citations_fingerprint(citations)
        trust_id = _trust_id_for(
            conversation_id=conversation_id,
            knowledge_base_id=knowledge_base_id,
            content_sha256=content_sha,
            citations_sha256=citations_sha,
        )
        path = _trust_root(settings) / f"{trust_id}.json"
        if not path.is_file() or path.is_symlink():
            return None
        raw = path.read_text(encoding="utf-8")
        record = json.loads(raw)
        if not isinstance(record, dict):
            return None
        payload = record.get("payload")
        signature = record.get("signature")
        if not isinstance(payload, dict) or not isinstance(signature, str):
            return None
        expected = hmac.new(
            _trust_secret(settings),
            _canonical_json(payload),
            hashlib.sha256,
        ).hexdigest()
        if not hmac.compare_digest(expected, signature):
            logger.warning("agent trust record signature mismatch: %s", trust_id)
            return None
        trusted = TrustedAnswer.model_validate(payload)
    except (OSError, ValueError, ValidationError, TrustStoreError) as error:
        logger.warning("agent trust record could not be verified (%s)", type(error).__name__)
        return None
    if trusted.trust_id != trust_id:
        return None
    if (
        trusted.conversation_id != conversation_id
        or trusted.knowledge_base_id != knowledge_base_id
        or trusted.content_sha256 != content_sha
        or trusted.citations_sha256 != citations_sha
    ):
        return None
    return trusted


__all__ = [
    "TRUST_DIRECTORY_NAME",
    "TRUST_SECRET_FILENAME",
    "GenerationSource",
    "TrustStoreError",
    "TrustedAnswer",
    "citations_fingerprint",
    "content_fingerprint",
    "record_streamed_answer",
    "verify_streamed_answer",
]
